void backtrack(vector<int>& nums, int start, int k, vector<int>& current, vector<vector<int>>& result) {
    if (current.size() == k) {
        result.push_back(current);
        return;
    }
    for (int i = start; i < nums.size(); i++) {
        current.push_back(nums[i]);        // choose
        backtrack(nums, i + 1, k, current, result); // explore, start moves to i + 1
        current.pop_back();                // unchoose
    }
}

vector<vector<int>> combine(int n, int k) {
    vector<int> nums(n);
    iota(nums.begin(), nums.end(), 1); // fills nums with 1, 2, ..., n
    vector<vector<int>> result;
    vector<int> current;
    backtrack(nums, 0, k, current, result);
    return result;
}

void backtrack(vector<int>& nums, int start, int k, vector<int>& current, vector<vector<int>>& result) {
    if (current.size() == k) {
        result.push_back(current);
        return;
    }
    int remainingNeeded = k - current.size();
    for (int i = start; i <= nums.size() - remainingNeeded; i++) {
        // the loop bound itself is the pruning: i can go at most up to
        // the point where exactly remainingNeeded candidates are still left
        current.push_back(nums[i]);
        backtrack(nums, i + 1, k, current, result);
        current.pop_back();
    }
}

vector<vector<int>> combineBitmask(int n, int k) {
    vector<vector<int>> result;
    for (int mask = 0; mask < (1 << n); mask++) {
        if (__builtin_popcount(mask) != k) continue;
        vector<int> current;
        for (int i = 0; i < n; i++) {
            if (mask & (1 << i)) current.push_back(i + 1);
        }
        result.push_back(current);
    }
    return result;
}
